const twilio = require("twilio");

// Phone-number verification through Twilio Verify. Twilio generates the code,
// texts it, enforces expiry and per-number attempt/send limits, and checks it —
// nothing about a code is stored or generated by us.
//
// Required (all three, or none — see lib/env.js):
//   TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN, TWILIO_VERIFY_SERVICE_SID
//
// This is the ONLY file that talks to Twilio. Routes call startVerification /
// checkVerification and turn a thrown VerifyError into an HTTP response with
// respondWithVerifyError — so every Twilio failure becomes a clear 4xx/503
// with a user-facing message instead of a raw 500.

const E164 = /^\+[1-9]\d{6,14}$/;

// Local development only: with no Twilio credentials and NODE_ENV !== "production",
// verification is stubbed — nothing is sent, and this fixed code is accepted — so
// the registration flow can be built and tested without spending SMS credit.
// Never active in production (see isDevStub).
const DEV_STUB_CODE = "123456";

// An error whose message is safe to show to the user, with the HTTP status the
// route should respond with.
class VerifyError extends Error {
  constructor(status, message) {
    super(message);
    this.name = "VerifyError";
    this.status = status;
  }
}

function isConfigured() {
  return Boolean(
    process.env.TWILIO_ACCOUNT_SID && process.env.TWILIO_AUTH_TOKEN && process.env.TWILIO_VERIFY_SERVICE_SID,
  );
}

function isDevStub() {
  return !isConfigured() && process.env.NODE_ENV !== "production";
}

let client = null;
function getClient() {
  if (!client) client = twilio(process.env.TWILIO_ACCOUNT_SID, process.env.TWILIO_AUTH_TOKEN);
  return client;
}

function verifyService() {
  return getClient().verify.v2.services(process.env.TWILIO_VERIFY_SERVICE_SID);
}

// Phone numbers are personal data — keep them out of logs except for the ends.
const mask = (to) => `${String(to).slice(0, 3)}…${String(to).slice(-3)}`;

// Twilio's error messages can quote our account SID (e.g. "…not valid for
// account AC…"). Not a credential by itself, but there's no reason for it to
// sit in log files, so any Twilio ID is cut down to its 2-letter prefix.
const scrub = (message) => String(message).replace(/(AC|VA|SK|SM)[0-9a-f]{32}/g, "$1…");

const INVALID_NUMBER =
  "That phone number doesn't look valid. Use international format, for example +2348012345678.";
const UNAVAILABLE = "We couldn't reach the verification service right now. Please try again shortly.";

// Twilio error code -> what we tell the user. Codes are from Twilio's Verify and
// REST API error reference. Anything not listed is handled by status below.
function mapTwilioError(err, action) {
  const code = err && err.code;
  const status = err && err.status;
  switch (code) {
    // The number itself is unusable.
    case 60200: // invalid parameter (e.g. malformed "To")
    case 21211: // invalid "To" phone number
    case 21614: // "To" is not a valid mobile number
      return new VerifyError(400, INVALID_NUMBER);
    case 60205: // SMS is not supported by this number (landline)
      return new VerifyError(400, "That number can't receive text messages (it may be a landline). Please use a mobile number.");
    // Twilio-enforced limits on a number.
    case 60203: // max send attempts reached for this number
      return new VerifyError(429, "Too many codes have been requested for this number. Please wait about 10 minutes and try again.");
    case 60212: // too many concurrent requests for this number
      return new VerifyError(429, "Too many requests for this number right now. Please wait a moment and try again.");
    case 60202: // max check attempts reached
      return new VerifyError(429, "Too many incorrect attempts. Please request a new code.");
    case 20429: // Twilio API rate limit
      return new VerifyError(429, "The verification service is busy. Please try again in a moment.");
    // The check found nothing pending: expired (10 min), already used, or never sent.
    // (On a *start*, 20404 instead means our Verify service ID is wrong — handled below.)
    case 20404:
      if (action === "check") {
        return new VerifyError(400, "That code has expired or was already used. Please request a new one.");
      }
      break;
    // Our Verify service itself is misconfigured: SMS is switched off on it. Not
    // the user's fault and not fixable by retrying, so it must not read as a
    // "bad number" — and it must be loud in the logs for whoever runs the account.
    case 60223:
      console.error(
        "[twilio] CONFIGURATION PROBLEM: the SMS channel is disabled on the Verify service " +
          "(error 60223). Enable SMS in Twilio Console > Verify > Services > this service.",
      );
      return new VerifyError(503, "Phone verification is temporarily unavailable. Please try again later.");
    // Blocked by Twilio (fraud protection / geo permissions / unverified trial number).
    case 60410:
    case 60605:
    case 60600:
    case 21408:
    case 21610:
      return new VerifyError(403, "We can't send a verification code to this number. If you think this is a mistake, please contact support.");
    default:
      break;
  }
  // Our own credentials / configuration are wrong: not the user's fault, and
  // worth shouting about in the logs.
  if (code === 20003 || code === 20404 || status === 401 || status === 403) {
    return new VerifyError(503, UNAVAILABLE);
  }
  if (status === 429) return new VerifyError(429, "The verification service is busy. Please try again in a moment.");
  if (status === 400) return new VerifyError(400, INVALID_NUMBER);
  return new VerifyError(503, UNAVAILABLE);
}

function assertUsable(to) {
  if (typeof to !== "string" || !E164.test(to)) throw new VerifyError(400, INVALID_NUMBER);
  if (!isConfigured() && !isDevStub()) {
    // Production without Twilio credentials: refuse loudly (lib/env.js should
    // already have stopped the server from booting this way).
    console.error("[twilio] Verification requested but Twilio Verify is not configured.");
    throw new VerifyError(503, "Phone verification isn't available right now. Please try again later.");
  }
}

// Texts a code to `to` (E.164). Resolves when Twilio has accepted the request.
async function startVerification(to) {
  assertUsable(to);
  if (isDevStub()) {
    console.log(`[DEV VERIFY — Twilio not configured] Would text a code to ${mask(to)}. Use code ${DEV_STUB_CODE}.`);
    return { status: "pending", dev: true };
  }
  try {
    const v = await verifyService().verifications.create({ to, channel: "sms" });
    console.log(`[twilio] verification ${v.status} for ${mask(to)}`);
    return { status: v.status };
  } catch (err) {
    console.error(`[twilio] start failed for ${mask(to)}: code=${err.code} status=${err.status} ${scrub(err.message)}`);
    throw mapTwilioError(err, "start");
  }
}

// Returns true only if `code` is the right, unexpired code for `to`.
// A wrong code is NOT an error from Twilio (it just isn't "approved"), so this
// returns false; an expired/unknown verification or an exceeded attempt limit
// throws a VerifyError.
async function checkVerification(to, code) {
  assertUsable(to);
  if (typeof code !== "string" || !/^\d{4,10}$/.test(code)) {
    throw new VerifyError(400, "Enter the 6-digit code we texted you.");
  }
  if (isDevStub()) return code === DEV_STUB_CODE;
  try {
    const check = await verifyService().verificationChecks.create({ to, code });
    return check.status === "approved";
  } catch (err) {
    console.error(`[twilio] check failed for ${mask(to)}: code=${err.code} status=${err.status} ${scrub(err.message)}`);
    throw mapTwilioError(err, "check");
  }
}

// Shared by every route that uses this file.
function respondWithVerifyError(res, err) {
  if (err instanceof VerifyError) return res.status(err.status).json({ message: err.message });
  console.error("[twilio] unexpected error:", err);
  return res.status(503).json({ message: UNAVAILABLE });
}

module.exports = {
  startVerification,
  checkVerification,
  respondWithVerifyError,
  VerifyError,
  isConfigured,
  E164,
  DEV_STUB_CODE,
};
